INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('chiang-shih', 'Ch''iang Shih', 'undead', 'rifts', 0, 'Always evil: Diabolic (01-50%), Miscreant (51-90%), Aberrant (91-00%)', '{"IQ":"1D4+5","ME":"1D6+6","MA":"1D6+2","PS":"2D6+20","PP":"2D6+12","PE":"1D6+12","PB":"1D6+12","Spd":"4D6+12"}', NULL, NULL, '2D4x10+33', '1D6x10+11', NULL, 'Also known as the Chinese Vampire. Race: Supernatural Entity. P.S. is Supernatural; Spd is running. Physical attributes are half in fully human form. Age in the current body (roll): 01-25% 1D6 months, I.Q. reduced by 30%; 26-60% 1D6 years; 61-80% 6D6 years; 81-90% 1D6x10+20 years, I.Q. +3 and M.D.C. +6D6; 91-00% 3D6x10+30 years, I.Q., M.A. and M.E. +5, P.S. +1D6 and M.D.C. +6D6+30. Equivalent level 1D4. At 20 M.D.C. below zero it is comatose; only burning the body sends the entity home.', NULL, 12, '{"attacks":5,"initiative":2,"strike":3,"parry":1,"dodge":2,"disarm":1,"pull":2,"roll":2}', '+1 attack for elders over 50 years, +2 for elders over 100. +6 save vs Horror Factor, +2 save vs mind control, +3 save vs possession; +6 to save vs all mind control from natural abilities. Elders (50+ years) may own one or two favourite weapons at +1 to strike and parry.', 'Speaks all languages 90% (only elders of 50+ years read), Track 55%, Land Navigation 88%, Climb 98%/88%, Concealment or Palming 50%, Pick Pockets or Pick Locks 50%, Streetwise or Seduction 40%, Prowl 50%, three Domestic skills of choice 50%. Skills do not improve.', 'Active only at night; sleeps by day in a hidden coffin. Slain (zero M.D.C.) it returns at the next sunset unless the body is burned. Must feed on blood: after two nights without, the body rots until the entity is expelled. Cannot enslave, control minds or make vampires. Forms: human (no powers), vampire, bird (50+ years: 60 mph/96 km, 600 ft/183 m ceiling, one attack fewer), black mist or shadow (untouchable, cannot attack, half Spd, +10% Prowl). Summons vermin, one type at a time: up to 100 rodents per 20 years of unlife (H.F. 10, 1D6+1 per melee round, controlled 10 minutes per 10 years) or 500 insects per 20 years (H.F. 8 flies, 10 roaches, 20 minutes per level); a swarmed victim loses one attack, -4 initiative, -2 strike, parry, dodge and others (-1 strike from insects), -20% skills from rodents. Breath attacks, save 16+ vs magic: Sleep Breath (obedient trance, 1 minute per 10 years of the vampire''s life, one attack); Icy Breath (10 ft/3 m radius, H.F. 15, 1D6 damage, two attacks); Death Breath (coma and death without treatment, no save bonuses; costs the vampire 20% of its original M.D.C. for good, four uses at most). Regenerates 3D6 M.D. per hour, whole by nightfall. Nightvision 1600 ft (488 m). No shadow. Needs no air, gives off no heat. Immune to stun, cold, disease, poison, drugs, possession, drowning, ordinary S.D.C. and M.D. weapons and psionics that harm the body. VULNERABILITIES: daylight leaves it inert (Globe of Daylight halves it for one minute, then coma; those under two years flee 01-65%). Blunt wooden weapons do 2D6 M.D., except willow. Electricity does double damage, lightning triple. Fire, magic and blessed weapons do normal damage. Will not attack the helpless or unaware. Two or more bells rung without a six-second pause bar it. Garlic, incense and strong odours hold it off (eating garlic: 1D4 M.D. per bite). Holy symbols: roll vs H.F. 18 or frozen one round; the symbol''s shadow does 1D6 M.D., 6D6 per round if it covers half the body.', 'None. Demonic curses: none.', 'None', 'Human, 5-6 ft (1.5 to 1.8 m); typically lean', '100-200 lbs (45 to 90 kg)', 'Presumably immortal as an entity; a body can last centuries', 'Throughout China, most in and around the Hells of the Yama Kings and dragon lands, usually urban; fewer in Russia, Mongolia, Southeast Asia and India; rare in Japan and Australia', 'None; loners that shun their own kind', 'All mortals as prey; dragons; greater demons, lords and gods who would command them; Western vampires', NULL, 'A demonic energy that animates a corpse and walks at night as a human-looking predator, feeding on blood and killing for sport. Unlike the Western vampire it has no slaves and cannot make more of its kind.', 'Rifts World Book 24: China 1 p.61-65'),
('kuei', 'Kuei', 'entity', 'rifts', 0, 'Always Diabolic', '{"IQ":"N/A","ME":"N/A","MA":"N/A","PS":"N/A","PP":"N/A","PE":"N/A","PB":"N/A","Spd":"1D6+10"}', NULL, NULL, '6D6+22', '6D6+40', NULL, 'Also known as the Demonic Ghost. Race: Supernatural Entity. Mental attributes and memories are roughly those of the dead person it copies; physical attributes do not apply. Equivalent level: the same as the person in life. Losing all M.D.C. only makes it vanish until the next night. H.F. 11 for acts of terror unseen, 15 with a frightening appearance.', NULL, 10, '{"attacks":4,"strike":1,"dodge":2,"pull":2}', '+6 save vs Horror Factor; impervious to possession and mind control; -3 to save vs illusion.', 'The languages the dead person knew and knowledge of the land around the grave. Skills from life do not apply and nothing improves.', 'Nightvision 1000 ft (305 m). Hovers and moves silently (Prowl 66%). Appears only at night or in fog, storm and darkness. Immune to most physical attacks and man-made weapons other than iron or steel, and to fire, cold, energy, disease and physical psionics. Flees at one third M.D.C. unless enraged. Terror (60 ft/18.3 m radius): a failed save vs H.F. 11, or 15 when it shows itself, means flight (01-50%) for 1D6x1000 ft or a faint (51-00%) for 2D6 minutes. Rule by fear: a save vs Horror Factor of 15 or less leaves the victim obedient; good characters get a second save (Unprincipled +3, Scrupulous +6, Principled +9, +2 more for heroes, clergy and those who serve the Celestial Court) and no one will kill a loved one, hero, holy person or child for it. Nightmares, once a night per mortal, save as vs psionics: -2 on all bonuses, -10% skills and -3 to save against this ghost afterwards. Its curse keeps it from killing outright. VULNERABILITIES: powerless against those who do not fear it. S.D.C. iron or steel weapons and tools do their damage as M.D. Susceptible to most magic. Stays within 2-8 miles (3.2 to 12.8 km) of its remains, and is destroyed when they are blessed and buried, or burned.', 'Calling (8), Extinguish Fire (4), Fear (5), Heavy Breathing (5), Lantern Light (1), Manipulate Objects (2+), Mask of Deceit (15), See the Invisible (4), Shatter (5), Sickness (50), Orb of Cold (6), Wave of Frost (6), and Curse of Minor Disorders (10). Demonic curses: none.', 'None', 'Human, 5-6 ft (1.5 to 1.8 m)', '100-200 lbs (45 to 90 kg)', 'Haunts as one person for days to centuries until laid to rest; the entity is presumably immortal', 'Throughout China, Mongolia, Japan and Russia; less common in Eastern Europe, India and the rest of Asia', 'None, though it keeps company with other demonic ghosts, must obey any Yama King, and may be forced to serve dark gods, Demon Lords, Shifters and evil sorcerers', 'All living mortals, the fortunate, admired and loved most of all', NULL, 'A spiteful ghost that takes on the personality of a cruel dead person and haunts the land around the grave, terrorising and manipulating the living. Burying or burning the remains ends it.', 'Rifts World Book 24: China 1 p.65-68'),
('preta', 'Preta', 'entity', 'rifts', 0, 'Always Diabolic', '{"IQ":"1D4+2","ME":"1D4+4","MA":"1D4+2","PS":"1D6+6","PP":"1D6+4","PE":"N/A","PB":"1D4","Spd":"1D6+6"}', NULL, NULL, '6D6+21', '6D6+44', '1D4x10+18', 'Also known as the Hungry Ghost. Race: Supernatural Entity. P.S. is Supernatural for damage. Equivalent level 1D4. H.F. +2 as a Whirling Cloud. At zero M.D.C. it vanishes and returns with the fourth moon of the next month.', NULL, 12, '{"attacks":3,"strike":1,"dodge":2,"pull":2}', '+6 save vs Horror Factor; impervious to possession and illusions; +3 save vs mind control and psionics.', 'Land Navigation 90%, Identify Plants and Fruits 90%, Cook 90%, one Lore of choice 90%. Skills do not improve.', 'Nightvision 1000 ft (305 m). Hovers and moves silently (Prowl 66%). Immune to all physical weapons, fire, cold, energy, disease and physical psionics. Fights down to its last M.D.C. point. Limited possession of an ordinary person (never a hero, noble, priest, monk or M.D. being) for 1D6+6 minutes; it cannot force what the victim strongly opposes. Possession to cause illness: best two of three opposed D20 rolls, possession bonuses only; the victim is ill while it stays, recovers within 12 hours, and is safe from it for a year after an exorcism. Illnesses: Delirium, Fever, Headaches, Hunger, Minor Disorder, Numbness, Stomach Sickness. Stench of blood, 50 ft (15.2 m) radius, doubled as a cloud: save 16+ vs non-lethal poison or lose three attacks and initiative; inside it -2 initiative, -20% skills and Spd. Whirling Cloud form: Spd x10, flies to 100 ft (30.5 m), slips through small openings. VULNERABILITIES: those who pity it or do not fear it are +2 to save against it. Susceptible to magic, psionics, magic weapons and exorcism; a Demon Queller can banish it for 200 years. Out only at night. Peach trees: it cannot shelter under one or cross peach twigs, peach-wood weapons do their S.D.C. as M.D., and a peach pit in its mouth kills it in 1D4 minutes.', 'Spoiling Magic: Curdle Milk (3), Cursed Bread (10), Dry Mother''s Milk (13), Sense Poison (3), Spoil and Taint Food (15), Spoil Eggs (6), Spoil Water (3), Spoil Wine (6). Invocations: Aura of Death (12), Cloak of Darkness (6), Death Trance (1), Fear (5), Repel Animals (7), Sickness (50), Spoil Water and Food (30), Turn Dead (6), Wave of Frost (6). Demonic curses: Delirium, Fever, Fleas, Hunger, Minor Disorder, Stomach Sickness.', 'Minor Psychic: Psychic Diagnosis (4), Suppress Fear (8), Sense Magic (3)', '3-4 ft (0.9 to 1.2 m) with a bloated belly', 'None measurable', 'Presumably immortal', 'Throughout China, Southeast Asia, Japan and Russia; sometimes Mongolia, Europe, India and Africa. Graveyards, battlefields, ruins, roads and crossroads; never more than 1D4 weeks in one place', 'None, though it keeps company with demons and demonic ghosts, must obey any Yama King, and may be forced to serve greater powers', 'All living mortals; families, children, pregnant women, priests, monks, heroes and Demon Quellers above all', NULL, 'The ghost of someone who died in shame or unburied, seen as a starving child with a swollen belly and a mouth too small to eat. It spoils food and crops, hates families, and makes people ill by possessing them.', 'Rifts World Book 24: China 1 p.68-70'),
('shen-mo', 'Shen Mo', 'entity', 'rifts', 0, 'Always Diabolic', '{"IQ":"1D4+3","ME":"1D6+6","MA":"1D4","PS":"1D6+20","PP":"1D6+16","PE":"N/A","PB":"1D4","Spd":"1D6+16"}', NULL, NULL, '6D6+66', '6D6x2+60', NULL, 'Also known as the Wicked Ghost and the Disease Demon. Race: Supernatural Entity. P.S. is Supernatural. Equivalent level 1D6. H.F. 15 as a demonic skeleton, 10 as a black vapor. At zero M.D.C. it falls into a heap of bones and returns the next night.', NULL, 15, '{"attacks":4,"strike":1,"parry":2,"pull":3}', 'Impervious to Horror Factor, possession and mind control; -3 to save vs illusion.', 'Land Navigation 80%, Prowl 55%, two Lore skills of choice. Skills do not improve.', 'Nightvision 1000 ft (305 m), sees the invisible. Hovers and moves silently (Prowl 55%). Immune to most physical attacks and man-made weapons other than iron or steel, and to fire, cold, energy, disease and physical psionics. Flees at 20% M.D.C. unless enraged or ordered. Black Vapor form: untouchable but cannot attack or use powers, +10% Prowl, one attack to re-form. Breath of disease (one attack, once per person per night): save 16+ vs non-lethal poison or take one illness for 1D4+1 days (Fever, Headaches, Minor Disorder, Numbness, Pox, Stomach Sickness). Once a night each, for one attack: 10 biting skulls per level (H.F. 10, 24 M.D.C., 3 attacks, bite 2D6, Spd 13 rolling or 6 hopping) and 10 headless skeletons per level (H.F. 12, 50 M.D.C., 3 attacks, 1D6+2 unarmed or 2D6+2 by sickle sword, Spd 13, +1 strike and parry); their damage is S.D.C. to mortals and M.D. to M.D.C. targets. Summons a sickle weapon for two attacks: a pole arm (3D6, +2 parry, +1 disarm) or a sickle-sword (2D4, +1 parry, thrown 200 ft/61 m and returns for one attack). Possession to cause illness: best two of three opposed D20 rolls; the victim is ill until it is driven out, recovers within 12 hours, and a mortal who wins is safe for 20 years. Illnesses: Delirium, Feebleness, Fever, Headaches, Minor Disorder, Numbness, Plague, Pox, Stomach Sickness, Wasting. VULNERABILITIES: no disease or curses against Demon Quellers or by day; out only at night, sleeping buried 3-6 ft (0.9 to 1.8 m) under a willow, graveyard or marsh. S.D.C. iron or steel weapons and tools do their damage as M.D. Susceptible to most magic. Destroyed only at zero M.D.C. with an iron spike through the skull, the skull buried by a priest or monk and the bones burned before the next sunset.', 'Aura of Death (12), Death Trance (1), Death Word (70), Fear (5), Mind Shatter (130), Minor Curse (35), Repel Animals (7), Sickness (50), Spoil Water and Food (30), Swords to Snakes (50), Turn Dead (6). Demonic curses: Animal Disease, Barrenness, Delirium, Drought, Feebleness, Fever, Headaches, Lameness, Numbness, Plague, Pox, Wasting.', 'None', '6-7 ft (1.8 to 2.1 m)', '200 lbs (90 kg)', 'Believed immortal', 'Throughout China and Mongolia; uncommon in Southeast Asia and Japan', 'Wanders alone or serves Witches, Shifters, Necromancers, evil sorcerers of 7th level or higher, Greater Demons, the Yama Kings and dark gods', 'All living mortals; the healthy, attractive, heroic and loved most, and priests. The sick and lame are left to suffer', NULL, 'A skeletal ghost with a hideous face that demands offerings and spreads sickness where it is refused, often as the enforcer of a stronger master. It breathes disease and calls up skulls, headless skeletons and sickle blades.', 'Rifts World Book 24: China 1 p.70-72'),
('vapours', 'Vapours', 'spirit', 'rifts', 0, 'Anarchist (75%) or Miscreant (25%)', '{"IQ":"1D4+4","ME":"1D6","MA":"1D6","PS":"1D6+16","PP":"1D6+6","PE":"N/A","PB":"1D6+4","Spd":"2D6+40"}', NULL, NULL, '3D6+10', 'MEx10', NULL, 'Also known as North Spirits and Goblin Lights. Race: a murderous nature spirit or lesser demon. P.S. is Supernatural. I.Q. is a predator''s cunning. Spd is for the vapor form, x10 as a Goblin Light, which has one S.D.C. Equivalent level: not applicable. H.F. 13 when one person faces four or more. Destroyed, it becomes a Goblin Light and returns the next night.', NULL, 10, '{"attacks":5,"initiative":1,"strike":3,"parry":1,"dodge":3,"pull":1}', '+7 to dodge as a Goblin Light. Impervious to Horror Factor; +2 save vs all magic.', 'Track Humans 80%, Prowl 80% day or night, Land Navigation 80%. Cannot speak or read.', 'Nightvision 2000 ft (610 m), sees the invisible, tracks by sight 80%. Out at night and in snow, storm and fog, in the shape of a bat, wolf, tiger, ape or the like made of frost and mist. Immune to S.D.C. weapons other than those of animal bone, tooth or claw, and to disease, cold and all fire. M.D. weapons, energy, explosives and magic do only 10% damage. Regenerates 1D6 M.D. per melee round. Goblin Light form at will: a grapefruit-sized globe, Spd x10, Prowl 80%, flies, +7 dodge, cannot attack; struck by any solid object it bursts and cannot return for 1D6 years. Vapour form hovers a foot (0.3 m) up and leaves no track, scent or heat; packs stay 1D6 days near a kill. Ignores anyone who hides or plays dead. VULNERABILITIES: weapons of animal bone, teeth or claws do their S.D.C. as M.D. Magic and holy weapons do full damage. Daylight turns it into a Goblin Light. It fears Monks and Demon Quellers: its claws do them half damage, the Chilling Touch nothing, and their bare S.D.C. blows hurt it as M.D.', 'None. Demonic curses: none.', 'None', 'About that of a large wolf or tiger', '40 lbs (18 kg) as vapor; weightless as a Goblin Light', 'Presumably immortal', 'Throughout China; now and then one to three in Mongolia and Russia; elsewhere only if summoned', 'Other Vapours, in packs of 1D4+2; obeys Elder Gods of nature or the elements', 'Mortals, hunters and warriors above all; avoids Monks and Demon Quellers', NULL, 'Cold spirits of the northern mountains that hunt at night as animals of frost and mist, or drift as small glowing orbs. They kill with claws or a freezing touch.', 'Rifts World Book 24: China 1 p.72-74'),
('fox-spirit', 'Fox Spirit', 'spirit', 'rifts', 0, 'Anarchist (75%) or Miscreant (25%)', '{"IQ":"1D6+10","ME":"1D6+14","MA":"1D6+12","PS":"1D6+8","PP":"1D6+11","PE":"1D6+12","PB":"1D6+18","Spd":"2D6+30"}', NULL, NULL, '1D6x10+48', 'PEx10', 'MEx2', 'Also known as Hu Yao Kuai; not the Fox Faerie. Race: an impish nature spirit or lesser demon. Damage is as per Supernatural P.S. Level of experience 1D6+1. H.F. 9 applies when it is invisible. Male or female, 50% each.', NULL, 9, '{"attacks":4,"initiative":2,"parry":1,"dodge":3,"pull":1}', '+4 save vs Horror Factor (not against dogs, Hunters or Demon Quellers); +2 save vs all magic; impervious to possession. Fox form: +1 dodge, +10% Prowl and Track, Spd +20%.', 'Speaks all languages, reads none. Dance 90%, Prowl 80% in darkness (50% by day), Swim 90%, Climb 80%/70%, Land Navigation 90%, Track Humans 60%, Track Animals 75%, Gambling or Seduction 70%, Pick Pockets or Palming 80%, Pick Locks or Concealment 80%, one Lore of choice 80%. Skills do not improve.', 'Nightvision 1000 ft (305 m), sees the invisible. Immune to S.D.C. weapons other than peach wood and iron or steel, and to disease and spoiled food; poison, cold and fire do half damage. Regenerates 2D6 M.D. per melee round. Invisible at will with no time limit, and can attack unseen. Takes the shape of an attractive human or a fox at will. Possession to cause illness: best two of three opposed D20 rolls, possession bonuses only; the victim has Fever or Delirium, and each blow on the victim with a peach switch (1 point) counts toward 1D6+5 strikes, after which there is a 01-33% chance it flees; recovery takes 4D6+24 hours. Summons 200 mice per level for 10 minutes per level (H.F. 10, 2D6+1 per melee round; the victim loses one attack, -4 initiative, -2 on combat moves, -20% skills). VULNERABILITIES: full damage from M.D. weapons, psionics and magic. S.D.C. iron or steel does its damage as M.D. Cannot resist raw fowl. Medium and large dogs are H.F. 15 to it, halve its bonuses, and force a disguised one into visible fox form. Hunters and Demon Quellers are H.F. 12 to it.', 'Armor of Ithan (10), Blind (6), Breathe Without Air (5), Chameleon (6), Charismatic Aura (10), Cure Illness (15), Escape (8), Fool''s Gold (10), Levitation (5), Luck Curse (40), Magic Pigeon (20), Mask of Deceit (15), Sense Magic (4), Sickness (50), Transferal (50). Demonic curses: Animal Disease, Bad Luck/Misfortune, Barrenness, Forefather, Interesting Life, Lameness, Minor Disorder, Rags.', 'Major Psychic: Alter Aura (2), Commune with Spirits (6), Deaden Senses (4), Death Trance (1), Mask I.S.P. and Psionics (7), Telepathy (4), Mind Block (4)', 'A large fox, 2-3 ft (0.6 to 0.9 m) at the shoulder; human-size in human form', '40 lbs (18 kg) as a fox; 100-160 lbs (45 to 72 kg) as a human', '1000 years', 'Throughout China; less common in Mongolia, Russia, Japan, India and Southeast Asia', 'Other Fox Spirits, in packs of 2D4; may keep company with were-beasts, nature spirits and thieves', 'Mortals are marks and meal tickets; dislikes ghosts and ugly demons; serves no one without profit', NULL, 'A cunning, cowardly trickster that passes as a handsome human or a fox, robbing and squatting in homes. It works unseen, sending illness and swarms of mice against its marks, and keeps well clear of dogs.', 'Rifts World Book 24: China 1 p.74-76'),
('goat-goblin', 'Goat Goblin', 'demon', 'rifts', 0, 'Anarchist (15%), Miscreant (65%), Diabolic (15%) or Aberrant (5%)', '{"IQ":"1D6+2","ME":"1D6+3","MA":"1D6+1","PS":"1D6+24","PP":"1D6+3","PE":"1D6+13","PB":"1D6","Spd":"2D6+30"}', NULL, NULL, '4D6x2+PE', '2D4x10+PE', NULL, 'Race: lesser demon. P.S. is Supernatural. M.D.C. is the night figure; daylight halves M.D.C., Spd, P.P.E. and combat bonuses (Globe of Daylight does the same after one minute). Equivalent level 1D4. Male or female, 50% each.', NULL, 10, '{"attacks":5,"strike":1,"parry":1,"pull":4}', 'Impervious to Horror Factor and possession; +1 save vs all magic. Goat form: +10 Spd, +1 dodge.', 'Speaks all languages, reads none. Climb 85%/75%, Land Navigation 90%, Skin Animals 90%, one Domestic and one Lore of choice 70%; Swim and Prowl 55% as a goat. Skills do not improve.', 'Nightvision 1000 ft (305 m), sees the invisible. Needs no air. Burrows at a quarter of running Spd; leaps 10 ft (3 m). Eats carrion, bone and refuse. Immune to S.D.C. weapons other than iron, and to disease, poison, rot and cold; no damage from S.D.C. fire, half from M.D. fire. Regenerates 1D6 M.D. per melee round, double in a graveyard''s shade. Stench Breath, 20 ft (6.1 m) radius: save 16+ vs non-lethal poison or lose three attacks and initiative; inside it -2 initiative, -20% skills and Spd. Terrifying Visage: +3 H.F., and a failed save leaves the victim mesmerised for up to 15 minutes. Goat form at any time: a rear kick does power punch damage as one attack, and a ram with the horns has a 01-66% chance to knock down a foe up to 10 ft (3 m) tall, who loses initiative and two attacks. VULNERABILITIES: halved by daylight as above. S.D.C. iron or steel does its damage as M.D. Magic, psionics and magic weapons do normal damage.', 'Death Trance (1), Manipulate Object (2+), Magic Shield (6), Mystic Fulcrum (5), Shatter (5), Throwing Stones (5), Barrage (15). Demonic curses: none.', 'None', '5 ft (1.5 m) as a Goblin; 3 ft (0.9 m) as a goat', '120 lbs (54 kg)', 'Unknown; at least 1000 years, perhaps immortal', 'Throughout China and Southeast Asia; one or two at a time in Japan, Mongolia, Russia and India', 'Alone, in pairs or with other Goblins; a henchman to evil sorcerers, Witches, Shifters, wicked dragons, Greater Demons, the Yama Kings and dark gods', 'Mortals as playthings and rivals; dislikes Fox Spirits', NULL, 'A brutish, corpse-eating goblin that can take the shape of a horned goat and bullies anything weaker. It gags foes with its breath and fixes them with a hideous face, and is far weaker by day.', 'Rifts World Book 24: China 1 p.76-77'),
('shadow-goblin', 'Shadow Goblin', 'demon', 'rifts', 0, 'Anarchist (15%), Miscreant (65%), Diabolic (15%) or Aberrant (5%)', '{"IQ":"1D6+5","ME":"1D6+3","MA":"1D6+5","PS":"1D6+19","PP":"1D6+15","PE":"1D6+13","PB":"1D6+5","Spd":"1D6+21"}', NULL, NULL, 'PEx4', '2D4x10+PE', NULL, 'Also known as the Goblin of Darkness and the Ghost Goblin. Race: an impish lesser demon. P.S. is Supernatural. M.D.C. is the night figure; daylight halves M.D.C. and combat bonuses. Equivalent level 1D6. H.F. 10 applies when invisible in darkness. Male 70%, female 30%. Killed at 30 M.D.C. below zero.', NULL, 10, '{"attacks":5,"strike":2,"parry":2,"dodge":1,"pull":4}', '+4 save vs Horror Factor; +1 save vs all magic; impervious to possession. Foes are -5 to strike, parry, dodge, disarm and entangle while it is invisible (-2 with enhanced hearing; heat or motion detectors cancel it).', 'Speaks all languages, reads none. Dance 75%, Prowl 90% in darkness (45% by day), Climb 85%/75%, Land Navigation 75%, Streetwise 55%, Gambling 75%, Cardsharp 70%, Pick Pockets 70%, Pick Locks 75%, Palming or Concealment 70%, one Domestic and one Lore of choice 70%. Skills do not improve.', 'Nightvision 3000 ft (914 m), sees the invisible. Immune to S.D.C. weapons other than iron, and to disease, poison, rot and cold; no damage from S.D.C. fire, half from M.D. fire. Regenerates 1D6 M.D. per melee round, double under a willow. Invisible in darkness with no time limit, and attacks unseen. Human disguise at will: short, dark, green-eyed and hairy; it holds all night and under artificial light. VULNERABILITIES: daylight (or Globe of Daylight after one minute) shows its true form and stops the disguise. If it truly surrenders it must obey the victor for an hour, answering truthfully. S.D.C. iron or steel does its damage as M.D.; magic, psionics and magic weapons do normal damage. The book numbers its weaknesses 1, 2, 3, 5.', 'Blinding Flash (1), Befuddle (6), Chameleon (6), Cloak of Darkness (6), Death Trance (1), Escape (8), See in Magic Darkness (32), Sense Magic (4), Shadow Meld (10). Demonic curses: none.', 'None', '4 ft (1.2 m); 5 to 5.5 ft (1.5 to 1.7 m) in human disguise', '90 lbs (40.5 kg); 140 lbs (63 kg) as a human', 'Unknown; at least 1000 years, perhaps immortal', 'Throughout China, Mongolia and Southeast Asia; one or two at a time in Japan, Russia and India', 'Alone or in pairs; a thief, spy, guard or henchman to evil sorcerers, Witches, Shifters, wicked dragons, Greater Demons, the Yama Kings and dark gods', 'Mortals as playthings and rivals to trick and abuse', NULL, 'A dark, rowdy goblin of taverns and gambling dens that vanishes in shadow and passes as a hairy little man. It brawls and cheats and will not admit defeat, because a true surrender binds it to the winner.', 'Rifts World Book 24: China 1 p.77-79'),
('mountain-goblin', 'Mountain Goblin', 'demon', 'rifts', 0, 'Anarchist (30%), Miscreant (60%) or Diabolic (10%)', '{"IQ":"1D4+3","ME":"1D6+1","MA":"1D6+3","PS":"1D6+18","PP":"1D6+17","PE":"1D6+13","PB":"1D4+1","Spd":"1D6+41"}', NULL, NULL, 'PEx3', 'PEx3', NULL, 'Also known as the Monkey Goblin. Race: an impish lesser demon. P.S. is Supernatural. M.D.C. is the night figure, half in the daytime. Spd is about 30-32 mph (48-51 km). Equivalent level 1D4. Male 70%, female 30%. At 8 M.D.C. it turns into a lump of flesh; killed at 30 M.D.C. below zero.', NULL, 8, '{"attacks":4,"initiative":2,"dodge":3,"pull":4}', '+6 save vs Horror Factor; +1 save vs all magic; impervious to possession.', 'Understands all languages, reads none, speaks only a few gruff words. Dance 80%, Prowl 80% in darkness (40% by day), Climb 85%/75%, Acrobatics 80%, Land Navigation 70%, Pick Locks 70%, Palming or Concealment 70%, one Domestic and one Lore of choice 70%. Skills do not improve.', 'Nightvision 1000 ft (305 m), sees the invisible. Immune to S.D.C. weapons other than iron, and to disease, poison, rot and cold; no damage from S.D.C. fire, half from M.D. fire. M.D. weapons, energy, explosives and magic do half damage. Regenerates 1D4 M.D. per melee round, double under a willow or on a ley line. Lump of flesh form (H.F. 12), automatic at 8 M.D.C.: immune to physical attack, magic does one third damage, and it can do nothing. At zero M.D.C. it is sent to the Dimension of Night for 2D6 years; one pledged to a Yama King is back within 48 hours. At first light, or after one minute of Globe of Daylight, it vanishes to its lair, leaving only the cap or scarf it stole. VULNERABILITIES: out only at night. S.D.C. iron or steel does its damage as M.D. Psionics on the mind and emotions work normally; physical psionic attacks do nothing.', 'Lantern Light (1), Concealment (6), Detect Concealment (6), Energy Bolt (5), Shatter (5). Demonic curses: none.', 'None', '3 ft to 3 ft 6 in (0.9 to 1.1 m)', '60 lbs (27 kg)', 'Unknown; perhaps immortal', 'Throughout China, Mongolia and Southeast Asia; one or two at a time in Japan, Russia and India', 'Alone, or with 3-6 other Goblins; a poor henchman to Witches, Shifters, evil sorcerers, demons and the Yama Kings', 'Mortals as playthings and rivals to trick and abuse', NULL, 'A small, furry night thief with a monkey''s face and a horse''s tail that snatches bright caps and scarves and taunts the owner into a chase. Cornered, it becomes a shapeless lump, and it is gone at dawn.', 'Rifts World Book 24: China 1 p.79-81'),
('one-horned-goblin', 'One-Horned Goblin', 'demon', 'rifts', 0, 'Anarchist (75%), Miscreant (15%), Diabolic (5%) or Aberrant (5%)', '{"IQ":"1D6+3","ME":"1D6+2","MA":"1D6+4","PS":"1D6+16","PP":"1D6+16","PE":"1D6+12","PB":"1D6+6","Spd":"1D6+16"}', NULL, NULL, 'PEx3', '2D4x10+PE', NULL, 'Headed One-Horned Mountain Goblin in its entry. Race: an impish lesser demon. P.S. is Supernatural. M.D.C. is the night figure, +24 in animal form. By day M.D.C., P.P.E., skills and the physical attributes are halved and it cannot change shape. Spd x3 as a stag, x2 as a deer. Equivalent level 1D6. Male 60%, female 40%. At 30 M.D.C. below zero it lies as if dead and rises with the next full moon unless its horn is cut off and ground to dust.', NULL, 8, '{"attacks":4,"initiative":1,"dodge":2,"pull":1}', '+4 to dodge in animal form. +4 save vs Horror Factor; +1 save vs all magic; impervious to possession. Its hands are a dog''s paws: -6 to strike with a tool, weapon or gun in them, -2 using its monkey-like feet.', 'Speaks all languages, reads none. Dance 75%, Prowl 60%, Climb 65%/55%, Swim 80%, Land Navigation 95%, Identify Plants and Fruits 90%, Preserve Food 80%, Brewing 70%, Dowsing 60%, Gardening 60%, one Domestic or two Lore of choice 70%. Skills do not improve.', 'Nightvision 1000 ft (305 m), sees the invisible. Immune to S.D.C. weapons other than iron, and to disease, poison, rot and cold; no damage from S.D.C. fire, half from M.D. fire. Regenerates 1D6 M.D. per melee round, double in the shade of a large boulder. Deer form at will and for as long as it likes (stag for males only): +1D6 M.D. on kicks and antler attacks, and it can still speak and cast. Rides a deer or stag as a tame horse: Spd about 50 (35 mph/56 km, 10% more for a stag), leaps 4 ft (1.2 m) high and 8 ft (2.4 m) across (half again for a stag), Hit Points 2D6+40 and S.D.C. 3D6 (+10 each for a stag). VULNERABILITIES: far weaker by day, as above. S.D.C. iron or steel does its damage as M.D. Magic, psionics and magic weapons do normal damage.', 'Earth Elemental spells: Dirt to Sand (6), Dust Storm (5), Hopping Stones (6), Identify Minerals (3), Mend Stone (15), Mystic Fulcrum (3), Shatter (3), Throwing Stones (4), Wither Plants (10). Demonic curses: none.', 'None', '4 ft (1.2 m); 5 to 5.5 ft (1.5 to 1.7 m) as a stag', '80 lbs (36 kg); 200 lbs (90 kg) as a stag', 'Unknown; at least 1000 years, perhaps immortal', 'Throughout China; one or two at a time in Mongolia, Japan and Russia', 'All Goblins are troublesome kin; alone, in pairs or with 3-6 of its own kind; now and then a messenger, escort or woodland scout for sorcerers, demons, Witches, the Yama Kings and dark gods', 'Anyone who shows it no respect; other Goblins as rivals; wary of powerful ghosts and demons', NULL, 'A horned, pig-eared earth spirit that plays tricks on travellers and may help those who leave it food and milk. It rides deer, the males can become stags, and it pays back a slight.', 'Rifts World Book 24: China 1 p.81-82'),
('tall-man-goblin', 'Tall Man Goblin', 'demon', 'rifts', 0, 'Miscreant (70%), Diabolic (25%) or Aberrant (5%)', '{"IQ":"1D6+8","ME":"1D6+10","MA":"1D6","PS":"1D6+20","PP":"1D6+16","PE":"1D6+16","PB":"1D6+1","Spd":"1D6+16"}', NULL, NULL, '6D6x3+16', '3D4x10+48', NULL, 'Race: a fiendish lesser demon. P.S. is Supernatural. M.D.C. +60 during storms. Daylight halves M.D.C., P.P.E. and Spd. Equivalent level 1D6+1. H.F. 13 applies once its true form is seen. Always male. P.B. 1D6+8 in human disguise.', NULL, 13, '{"attacks":6,"initiative":2,"strike":1,"parry":1,"pull":3}', 'Impervious to Horror Factor and possession; +1 save vs all magic. Foes are -2 to parry and dodge the tongue. By day it is blind: -10 to strike, parry, dodge and all combat moves (Globe of Daylight: -2 only).', 'Speaks all languages, reads none. Horsemanship: Knight 80%, Horsemanship: Exotic Animals 70%, Recognize Weapon Quality 80%, Climb 80%/70%, Land Navigation 80%, Track Humanoids 80%, Roadwise 80%, Basic Math 80%, W.P. Sword, W.P. Spear, one Lore of choice 70%. Skills do not improve.', 'Nightvision 3000 ft (914 m), sees the invisible. Immune to S.D.C. weapons other than iron, and to disease, poison, rot, cold, electricity and lightning. Regenerates 2D6 M.D. per melee round, double in a storm or under a willow; a storm restores everything, lost limbs included, within 45 minutes. Passes as a human, or copies any man it has met since dusk, voice and manner included, never a woman. Butterfly form as a last escape: flies 20 mph (32 km), +5 dodge, gone within one melee round, and it cannot come back to that place for 30 days. Its tongue reaches 5 ft (1.5 m) and strikes like a spear, as one attack. Any S.D.C. sword or spear in its hands becomes an M.D. weapon doing its damage +1D6 M.D. VULNERABILITIES: lightning and electricity show its true form without harming it. Daylight withers and blinds it. S.D.C. iron or steel does its damage as M.D.; magic, psionics and magic weapons do normal damage. To kill it for good: zero M.D.C., beheading with a weapon that belongs to it, burial of the body by a priest and then the head thrown into moving water, all before the next nightfall, or it returns with the next storm.', 'Earth Elemental spells: Animate Plants (10), Dust Storm (5), Earth Rumble (10), Hopping Stones (6), Identify Minerals (3), Mend Stone (15), Metal to Clay (40), Mystic Fulcrum (3), Repel Animals (10), Rust (15), Shatter (3), Track (6), Travel Through Walls (20), Wall of Thorns (15), Wither Plants (10). Demonic curses: none.', 'None', '6-7 ft (1.8 to 2.1 m)', '150 lbs (67.5 kg)', 'Unknown; at least 1000 years, perhaps immortal', 'Throughout China and Mongolia; now and then in Russia, Southeast Asia and Japan', 'None; a lone hunter that serves a greater being only until it wins its freedom', 'All mortals are prey; other Goblins, demons and spirits are rivals', NULL, 'The largest of the Chinese goblins, a gaunt horseman with a long spear of a tongue that hunts alone on stormy nights. It wears the faces of men it has met and slips away as a butterfly when beaten.', 'Rifts World Book 24: China 1 p.82-84');
